$add('city.faq1.q', 'city', 'FAQ', 'Вопрос 1', 'Ո՞ր բանկերն ունեն մասնաճյուղ {city_loc}', 'В каких банках есть отделения в городе {city}?', 'Which banks have branches in {city}?', false);
