$add('city.faq2.a', 'city', 'FAQ', 'Ответ 2', 'Այս քաղաքում ներկայացված բանկերից դոլարի առքի լավագույն կուրսը {best_buy} ֏ է ({best_bank})։', 'Среди банков города {city} лучшая покупка доллара — {best_buy} AMD ({best_bank}).', 'Among the banks present in {city}, the best dollar buy rate is {best_buy} AMD ({best_bank}).', true);

