$add('method.lead', 'method', 'Тексты', 'Вводный абзац', 'Այստեղ նկարագրված է, ինչպես են ստացվում Poxarjeq.am-ի թվերը՝ {bank_n} բանկի և {cur_n} արժույթի համար։ Այսպես կարող եք ստուգել, թե ինչին կարելի է վստահել և ինչը պետք է ճշտել բանկում։', 'Здесь описано, как получаются цифры Poxarjeq.am по {bank_n} банкам и {cur_n} валютам. Так вы поймёте, чему можно доверять, а что нужно уточнить в банке.', 'This page describes how the Poxarjeq.am figures are produced for {bank_n} banks and {cur_n} currencies. It shows what you can rely on and what to confirm with the bank.', true);
$add('method.ex_update', 'method', 'Тексты', 'Время обновления пунктов', 'Փոխանակման կետեր՝ թարմացված է {time}', 'Обменные пункты: обновлено {time}', 'Exchange offices: updated {time}');
$add('method.s1_title', 'method', 'Разделы', '1: заголовок', 'Որտեղից են տվյալները', 'Откуда данные', 'Where the data comes from');
$add('method.s1_text', 'method', 'Разделы', '1: текст', 'Բանկերի և փոխանակման կետերի կանխիկ կուրսերը հավաքվում են Poxarjeq.com-ի տվյալների բազայում՝ նրանց հրապարակած աղբյուրներից։ Poxarjeq.am-ը այդ բազայից է վերցնում թվերը և ցուցադրում դրանք բանկերի, արժույթների, քաղաքների և փոխանակման կետերի էջերում։', 'Наличные курсы банков и обменных пунктов собираются в базе данных Poxarjeq.com из опубликованных ими источников. Poxarjeq.am берёт цифры из этой базы и показывает их на страницах банков, валют, городов и обменных пунктов.', 'The cash rates of banks and exchange offices are collected in the Poxarjeq.com database from the sources they publish. Poxarjeq.am takes the figures from that database and shows them on the pages of banks, currencies, cities and exchange offices.', true);
$add('method.s2_title', 'method', 'Разделы', '2: заголовок', 'Որքան հաճախ են թարմացվում', 'Как часто обновляются', 'How often it updates');
$add('method.s2_text', 'method', 'Разделы', '2: текст', 'Կուրսերը թարմացվում են մոտ 15 րոպեն մեկ, ոսկու գինը՝ օրը մեկ անգամ։ Յուրաքանչյուր էջում նշված է տվյալների վերջին թարմացման ժամը։ Եթե բանկը օրվա ընթացքում կուրսը փոխել է մեր թարմացումից հետո, այդ փոփոխությունը կերևա հաջորդ թարմացմանը։', 'Курсы обновляются примерно каждые 15 минут, цена золота — раз в день. На каждой странице указано время последнего обновления данных. Если банк изменил курс после нашего обновления, изменение появится при следующем.', 'Rates update about every 15 minutes and the gold price once a day. Every page shows the time of the last data update. If a bank changes its rate after our update, the change appears at the next one.', true);
$add('method.s3_title', 'method', 'Разделы', '3: заголовок', 'Ինչ է «լավագույն կուրսը»', 'Что считается «лучшим курсом»', 'What counts as the «best rate»');
$add('method.s3_text', 'method', 'Разделы', '3: текст', 'Լավագույն առքի կուրսը ամենաբարձր առքի կուրսն է, որովհետև այդ գնով բանկը գնում է ձեր արժույթը։ Լավագույն վաճառքի կուրսը ամենացածր վաճառքի կուրսն է։ Մենք չենք հաշվում «միջին» կամ «վարկանիշային» կուրսեր. թվերը բանկերի հրապարակածներն են։', 'Лучшая покупка — самый высокий курс покупки, потому что по нему банк покупает вашу валюту. Лучшая продажа — самый низкий курс продажи. Мы не считаем «усреднённых» или «рейтинговых» курсов: цифры — те, что опубликовали банки.', 'The best buy rate is the highest buy rate, because that is what the bank pays for your currency. The best sell rate is the lowest sell rate. We do not compute «averaged» or «rated» rates: the figures are those the banks publish.', true);
$add('method.s4_title', 'method', 'Разделы', '4: заголовок', 'Բանկերի տեղը և գործընկերները', 'Место банков и партнёры', 'Bank positions and partners');
$add('method.s4_text', 'method', 'Разделы', '4: текст', 'Բանկի տեղը աղյուսակում որոշվում է առքի կուրսով։ Որոշ բանկեր Poxarjeq-ի գործընկերներ են. նրանք նշված են «Գործընկեր» պիտակով և կարող են հայտնվել ցանկի սկզբում, բայց նրանց կուրսերը չեն փոփոխվում։', 'Место банка в таблице определяется курсом покупки. Некоторые банки — партнёры Poxarjeq: они отмечены меткой «Партнёр» и могут стоять в начале списка, но их курсы мы не меняем.', 'A bank\'s position in the table is decided by its buy rate. Some banks are Poxarjeq partners: they carry a «Partner» label and may appear at the top of the list, but their rates are never altered.', true);
$add('method.s5_title', 'method', 'Разделы', '5: заголовок', 'Սխալներ և ուղղումներ', 'Ошибки и исправления', 'Errors and corrections');
$add('method.s5_text', 'method', 'Разделы', '5: текст', 'Եթե տվյալն ակնհայտ սխալ է, գրեք info@leads.am հասցեին՝ նշելով էջը և ճիշտ թիվը։ Կարող ենք ստուգել աղբյուրը և ուղղել։ Կայքը գործարք չի կատարում, ուստի վերջնական կուրսը միշտ սահմանում է բանկը։', 'Если цифра явно неверна, напишите на info@leads.am с адресом страницы и правильным значением. Мы проверим источник и исправим. Сайт не проводит сделок, поэтому итоговый курс всегда устанавливает банк.', 'If a figure is clearly wrong, write to info@leads.am with the page address and the correct value. We will check the source and fix it. The site does not execute transactions, so the final rate is always set by the bank.', true);
